"use client";

import { useEffect, useRef, type PointerEvent } from "react";

/*
 * SPEED PASS. Same story, same beats, same order, same artwork — re-paced.
 *
 * Timing is authored in MILLISECONDS below and the keyframe percentages are
 * derived from INTRO_DURATION_MS. The previous version expressed every beat as
 * a hand-written percentage of a shared 10,400ms timeline, which meant a change
 * to the duration silently rescaled all fourteen beats; a beat is now moved by
 * editing its own two numbers.
 *
 * The timeline is FORWARD-ONLY and runs once (`iteration-count: 1`,
 * `fill-mode: both`), so it finishes holding the connected result. It used to be
 * a palindrome: build over the first half, dismantle over the second, parked at
 * the 50% mark by a timer. That second half is what made a hover replay 10.4s
 * and made it start by taking the result apart. There is no teardown half now,
 * so a replay is a seek to 0 — the accepted forward story, again.
 */

/** Semantic beats, ms from the intro trigger. Order is the accepted story. */
const BEATS = {
  /** Workspace panel travels to its resting position. Starts immediately. */
  workspace: [0, 420],
  /** Gradient masks that fade the file list's top and bottom edges. */
  fadeMask: [60, 420],
  /** auth.ts row lifts and its icon goes grey -> Beam blue. */
  authFocus: [320, 540],
  /** The "-> Agent reading" marker on that row. */
  reading: [420, 620],
  /** Connector draws from its origin down into the composition. */
  connector: [560, 980],
  /** Agents panel resolves: opacity plus the 12px Y settle. */
  panel: [900, 1280],
  /** "Connected" status check. */
  connected: [1180, 1340],
  /** The scope group — one fast readable sweep at a 60ms stagger. */
  verbList: [1260, 1400],
  verbRead: [1320, 1460],
  verbWrite: [1380, 1520],
  verbGlob: [1440, 1580],
  /** First consequence. */
  audit: [1580, 1760],
  /** Second consequence, 80ms later so both read separately. Also lifts the
   *  cover that hides this row's static artwork until its moment. */
  sandbox: [1660, 1840],
} as const;

/** Result is readable at BEATS.sandbox[1] (1840ms); the tail is the quiet settle. */
const INTRO_DURATION_MS = 2300;

/*
 * Hover rewinds the SAME story and plays it again — it does not cut to the
 * start, and it does not introduce a transition of its own. The reverse is the
 * forward timeline at a negative playback rate, so every beat retraces in
 * reverse order (Sandbox ready retracts first, then Audit logged, then the
 * scope verbs backwards, Connected, the panel leaving, the connector
 * retracting, the reading marker, auth.ts losing focus, and the workspace
 * returning to its start pose) with no extra keyframes anywhere.
 *
 * A rate is used rather than a shorter reverse timeline because the rewind must
 * stay the accepted choreography: same keyframes, same relative proportions,
 * just wound back quickly. The old 10.4s palindrome is NOT coming back.
 */
const HOVER_REVERSE_DEFAULT_MS = INTRO_DURATION_MS;
const HOVER_REPLAY_DEFAULT_MS = INTRO_DURATION_MS;
/** Authoring bounds for both hover durations. Mirrored by the dev dials. */
const HOVER_DURATION_MIN_MS = 300;
const HOVER_DURATION_MAX_MS = 3000;
/**
 * Beat of stillness at the start pose, between the rewind and the replay.
 *
 * It is a CONTROLLER pause, not a timeline change: the rewind lands on exact
 * currentTime 0, every animation is paused there, and the replay starts after
 * this delay. Nothing is added to the authored 2300ms story, which still has no
 * dead time of its own.
 */
const HOVER_HOLD_DEFAULT_MS = 300;
const HOVER_HOLD_MIN_MS = 0;
const HOVER_HOLD_MAX_MS = 1000;

/**
 * DEV-ONLY hover pacing seam. Absent in production, where both halves run the
 * authored timeline at 1x. These are DURATIONS, not new timelines: each one is
 * turned into a playback rate over the same 2300ms keyframes, so no beat, easing
 * or offset changes — only how fast the existing story is wound.
 */
export type AgentHoverTuning = {
  /** ms for the settled -> start rewind. Default INTRO_DURATION_MS (1x). */
  reverseDurationMs?: number;
  /** ms paused on the start pose before replaying. Default HOVER_HOLD_DEFAULT_MS. */
  startHoldMs?: number;
  /** ms for the start -> settled replay. Default INTRO_DURATION_MS (1x). */
  replayDurationMs?: number;
};

/**
 * duration -> playback rate. rate = INTRO_DURATION_MS / duration, so 2300ms is
 * 1x, 1150ms is 2x and 3000ms is ~0.767x. The reverse half additionally runs
 * negative, which is what makes it retrace the same beats backwards.
 */
export function resolveHoverTiming(tuning?: AgentHoverTuning) {
  const clamp = (
    value: number | undefined,
    fallback: number,
    min: number,
    max: number,
  ) =>
    typeof value === "number" && Number.isFinite(value)
      ? Math.min(max, Math.max(min, value))
      : fallback;
  const bounds = [HOVER_DURATION_MIN_MS, HOVER_DURATION_MAX_MS] as const;
  const reverseMs = clamp(
    tuning?.reverseDurationMs,
    HOVER_REVERSE_DEFAULT_MS,
    ...bounds,
  );
  const replayMs = clamp(
    tuning?.replayDurationMs,
    HOVER_REPLAY_DEFAULT_MS,
    ...bounds,
  );
  const holdMs = clamp(
    tuning?.startHoldMs,
    HOVER_HOLD_DEFAULT_MS,
    HOVER_HOLD_MIN_MS,
    HOVER_HOLD_MAX_MS,
  );
  return {
    reverseMs,
    holdMs,
    replayMs,
    totalMs: reverseMs + holdMs + replayMs,
  };
}

/**
 * Solver for a CSS-style cubic-bezier easing, used by the hover REVERSE clock.
 *
 * The forward story keeps its authored CSS easing untouched; this exists only
 * because the rewind is scrubbed by the controller rather than played by the
 * animation engine, so its progress curve has to be evaluated in JS.
 */
function cubicBezier(p1x: number, p1y: number, p2x: number, p2y: number) {
  const cx = 3 * p1x;
  const bx = 3 * (p2x - p1x) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * p1y;
  const by = 3 * (p2y - p1y) - cy;
  const ay = 1 - cy - by;
  const sampleX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const sampleY = (t: number) => ((ay * t + by) * t + cy) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;

  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    // Newton-Raphson, then bisection for the flat-slope tail of this curve.
    let t = x;
    for (let i = 0; i < 8; i += 1) {
      const error = sampleX(t) - x;
      if (Math.abs(error) < 1e-6) return sampleY(t);
      const slope = slopeX(t);
      if (Math.abs(slope) < 1e-6) break;
      t -= error / slope;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 24; i += 1) {
      const value = sampleX(t);
      if (Math.abs(value - x) < 1e-6) break;
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return sampleY(t);
  };
}

/**
 * MASTER progress curve for a hover transaction — both directions.
 *
 * Balanced ease-in-out: zero velocity at both ends, momentum through the middle.
 * Zero velocity at the start is what removes the jump on the first replay frame
 * after the hold, and zero velocity at the end is what removes the snap at
 * frame 1. One curve for both directions is what makes the rewind and the replay
 * read as the same hand.
 *
 * This governs how fast the composition travels THROUGH authored time. It is not
 * a substitute for the authored per-beat easing, which still applies when each
 * animation is evaluated at the authored time this curve selects.
 */
const easeMaster = cubicBezier(0.42, 0, 0.58, 1);

/**
 * Blur carried by the two final consequences only, in SVG user units. They are
 * the result of the story, so they resolve OUT of a soft state rather than
 * popping; every other beat stays opacity/colour only. Kept modest on purpose —
 * this is a product reveal, not a cinematic rack focus.
 */
const CONSEQUENCE_BLUR_PX = 4;

/** ms -> keyframe offset. Every percentage in the sheet comes from here. */
const at = (ms: number) => `${((ms / INTRO_DURATION_MS) * 100).toFixed(4)}%`;
/**
 * A beat: hold the start value, transition once, then hold the end value.
 *
 * The trailing 100% keyframe is NOT redundant. When a 100% keyframe is absent
 * the UA synthesises one from the element's own base style and animates towards
 * it, so an unpinned beat drifts back to its authored value over the remainder
 * of the timeline. The connector is the case that proves it — its base style is
 * `stroke-dashoffset: 1`, so without this it drew in by 980ms and then quietly
 * un-drew itself across the settle. Every end state is pinned.
 */
const beat = (
  [start, end]: readonly [number, number],
  from: string,
  to: string,
) => `${start > 0 ? `0%, ${at(start)}` : "0%"} { ${from} }
          ${at(end)}, 100% { ${to} }`;

