export function AgentVisual({
  hoverTuning,
}: { hoverTuning?: AgentHoverTuning } = {}) {
  /*
   * DEV-ONLY seam. Absent in production, where hover runs both halves at 1x.
   * This component imports nothing from src/dev, knows nothing about DialKit and
   * never touches storage — the Motion Lab passes plain milliseconds in.
   *
   * Read through a ref because the hover handler is created once per render but
   * must always use the values current at the moment of the hover.
   */
  const hoverTimingRef = useRef(resolveHoverTiming(hoverTuning));
  hoverTimingRef.current = resolveHoverTiming(hoverTuning);

  const frameRef = useRef<HTMLDivElement>(null);
  const replayRunningRef = useRef(false);
  const stopTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  /** rAF handle of the hover master clock (drives both rewind and replay). */
  const scrubFrameRef = useRef<number | null>(null);

  const clearStopTimer = () => {
    if (stopTimerRef.current) {
      clearTimeout(stopTimerRef.current);
      stopTimerRef.current = null;
    }
    if (scrubFrameRef.current !== null) {
      cancelAnimationFrame(scrubFrameRef.current);
      scrubFrameRef.current = null;
    }
  };

  /*
   * One hover transaction:
   *
   *   settled -> reverse -> start state -> HOLD -> forward replay -> settled
   *
   * BOTH moving phases are SCRUBBED by the controller on ONE master progress:
   * reverse walks it 1 -> 0, replay walks it 0 -> 1, and each frame maps it to a
   * single authored time that is written to all 21 animations. Nothing is played
   * by the animation engine during a hover. No second timeline, no
   * reverse-specific CSS, no per-element playback clocks.
   *
   * That last point is the fix for the panel appearing to leap out of step.
   * Replay used to be engine-played at a playback rate: 21 animations, each
   * started by its own play() call, each advancing on its own clock. Small
   * start-time skew plus each element's own authored easing meant the front
   * loaded beats — the panel's ease-out across 900-1280ms most visibly — read as
   * jumping ahead of the composition instead of arriving with it. With one
   * master clock there is only one time in the system, so nothing can advance
   * independently; the authored beats keep their exact relationships because the
   * animations are still EVALUATED at the authored time, per-beat easing and all.
   *
   * Earlier faults this also keeps fixed: a constant negative playbackRate ended
   * by a timer raced the engine clock (bounce at frame 1, held pose left to
   * chance) and ran at full speed into the stop (abrupt halt). The master curve
   * is a balanced ease-in-out, so velocity is ~0 at BOTH ends — no snap into
   * frame 1, and no jump on the first replay frame after the hold.
   *
   * Reverse Duration and Replay Duration are the spans the master curve is
   * evaluated over; they set how long the composition takes to travel the
   * authored timeline, never what the timeline contains.
   *
   * The hold is genuinely static — the animations are already paused and pinned
   * at authored time 0, so nothing needs to hold still, it simply is still.
   *
   * Timing is SNAPSHOT here, at the start of the transaction, so a dial moved
   * mid-hover cannot desynchronise phases that are already scheduled.
   */
  const playOneReplay = () => {
    const frame = frameRef.current;
    // The guard covers the WHOLE transaction, so a pointer re-entry mid-rewind,
    // mid-hold or mid-replay is ignored rather than stacking a second run. A
    // pointer leave is not handled at all: the transaction always finishes.
    if (!frame?.classList.contains("agent-loop-ready") || replayRunningRef.current) return;

    clearStopTimer();
    replayRunningRef.current = true;
    const { reverseMs, holdMs, replayMs } = hoverTimingRef.current;

    const release = () => {
      replayRunningRef.current = false;
      stopTimerRef.current = null;
      scrubFrameRef.current = null;
    };

    /*
     * ONE master progress owns the whole transaction.
     *
     * Every frame, master progress is mapped to a single authored time and that
     * exact time is written to all 21 animations. Nothing is played by the
     * animation engine during hover, so there are no 21 independent playback
     * clocks to drift apart — the composition can only move as one.
     *
     * The authored per-beat easing is untouched: each animation is still
     * EVALUATED at the authored time, so the panel still resolves across
     * 900-1280ms with its own curve. What the master curve changes is how fast
     * the composition travels through authored time, not what happens when it
     * gets there.
     */
    const pinAll = (authoredTime: number) => {
      const current = frameRef.current;
      if (!current) return false;
      for (const animation of current.getAnimations({ subtree: true })) {
        animation.currentTime = authoredTime;
      }
      return true;
    };

    /**
     * Scrub master progress from -> to over durationMs, then hand off.
     * Used for BOTH directions, which is what makes them feel like one motion.
     */
    const scrub = (
      fromProgress: number,
      toProgress: number,
      durationMs: number,
      onDone: () => void,
    ) => {
      let settled = false;
      const finish = () => {
        if (settled) return;
        settled = true;
        if (scrubFrameRef.current !== null) {
          cancelAnimationFrame(scrubFrameRef.current);
          scrubFrameRef.current = null;
        }
        if (stopTimerRef.current) {
          clearTimeout(stopTimerRef.current);
          stopTimerRef.current = null;
        }
        // Land on the exact endpoint rather than wherever the last frame fell.
        if (!pinAll(toProgress * INTRO_DURATION_MS)) {
          release();
          return;
        }
        onDone();
      };

      const startedAt = performance.now();
      const step = (now: number) => {
        const x = Math.min(1, (now - startedAt) / durationMs);
        const progress =
          fromProgress + (toProgress - fromProgress) * easeMaster(x);
        if (!pinAll(progress * INTRO_DURATION_MS)) {
          release();
          return;
        }
        if (x >= 1) {
          finish();
          return;
        }
        scrubFrameRef.current = requestAnimationFrame(step);
      };

      scrubFrameRef.current = requestAnimationFrame(step);
      /*
       * Safety net. requestAnimationFrame is suspended while the tab is hidden,
       * so without this a transaction interrupted by a tab switch would stall
       * mid-pose and latch the re-entry guard. Timers still fire, so this
       * completes the phase through the same path.
       */
      stopTimerRef.current = setTimeout(finish, durationMs + 250);
    };

    /*
     * Paused for the entire transaction — the controller owns the clock. The
     * rate is normalised here, while paused, so it can never cause a direction
     * flip, and so the element is in a known state afterwards.
     */
    const animations = frame.getAnimations({ subtree: true });
    for (const animation of animations) {
      animation.pause();
      animation.playbackRate = 1;
    }
    // Rewind from where it actually is, not from an assumed settled state.
    const fromProgress = Math.min(
      1,
      Math.max(0, Number(animations[0]?.currentTime ?? INTRO_DURATION_MS) / INTRO_DURATION_MS),
    );

    // Phase 1 — rewind to exact frame 1.
    scrub(fromProgress, 0, reverseMs, () => {
      // Phase 2 — hold. Everything is already paused and pinned at authored
      // time 0, so the hold is still by construction.
      stopTimerRef.current = setTimeout(() => {
        if (!frameRef.current) {
          release();
          return;
        }
        // Phase 3 — replay forward on the same master clock, from a standstill.
        scrub(0, 1, replayMs, release);
      }, holdMs);
    });
  };

  /*
   * Capability, not viewport width: the pointer that actually generated the
   * event decides. A mouse or pen replays on hover exactly as before; a finger
   * gets no hover, so it replays on tap. A hybrid laptop with both gets each
   * behaviour from the device it is actually using at that moment.
   */
  const startMotion = (event: PointerEvent<HTMLDivElement>) => {
    if (event.pointerType === "touch" || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    playOneReplay();
  };

  /*
   * pointerup, not click: the browser fires pointercancel instead when the
   * gesture turns into a scroll, so a scroll that happens to start on the
   * visual cannot be mistaken for a tap. playOneReplay is already guarded by
   * agent-loop-ready and replayRunningRef, so a tap before the intro has
   * settled, or during a run, is ignored rather than stacking a second one.
   */
  const replayOnTap = (event: PointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "touch" || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    playOneReplay();
  };

  useEffect(() => {
    const frame = frameRef.current;
    if (!frame || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    const startInitialMotion = () => {
      frame.classList.add("agent-motion-active");
      // The timeline holds its final state on its own, so this only marks the
      // point from which a hover replay is allowed.
      stopTimerRef.current = setTimeout(() => {
        frame.classList.add("agent-loop-ready");
        stopTimerRef.current = null;
      }, INTRO_DURATION_MS);
    };

    if (!("IntersectionObserver" in window)) {
      startInitialMotion();
      return clearStopTimer;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return;
        observer.disconnect();
        startInitialMotion();
      },
      { threshold: 0.35 },
    );

    observer.observe(frame);

    return () => {
      observer.disconnect();
      clearStopTimer();
    };
  }, []);

  return (
    <div
      ref={frameRef}
      className="agent-visual-frame"
      onPointerEnter={startMotion}
      onPointerUp={replayOnTap}
    >
      <div
        className="on-demand-visual agent-svg"
        role="img"
        aria-label="Beam agent access connected to a workspace with audited sandbox permissions"
        dangerouslySetInnerHTML={{ __html: svgMarkup }}
      />
      <div className="agent-top-fade" aria-hidden="true" />
      <div className="agent-confirmation-cover" aria-hidden="true" />
      <div className="agent-hover-surface" aria-hidden="true" />
      <style>{`
        .agent-visual-frame { position: relative; isolation: isolate; width: 100%; max-width: 809px; overflow: hidden; background: #fafafa; }
        .agent-svg { position: relative; z-index: 0; }
        .agent-svg, .agent-svg svg { display: block; width: 100%; height: auto; }
        .agent-top-fade {
          position: absolute; z-index: 20; inset: 0 0 auto; height: 24%; pointer-events: none;
          background: linear-gradient(to bottom, #fafafa 0%, #fafafa 34%, rgba(250,250,250,.96) 48%, rgba(250,250,250,.72) 66%, rgba(250,250,250,.28) 84%, rgba(250,250,250,0) 100%);
        }
        .agent-svg foreignObject[x="-346.992"],
        .agent-svg g[filter="url(#filter4_i_964_1383257)"] { display: none; }
        .agent-svg .agent-connector-mask {
          stroke-dasharray: 1; stroke-dashoffset: 1;
        }
        .agent-confirmation-cover {
          position: absolute; z-index: 21; left: 39.8%; top: 72.9%; width: 45.8%; height: 6.4%;
          background: #fafafa; opacity: 0; pointer-events: none;
        }
        .agent-hover-surface { position: absolute; inset: 0; z-index: 30; cursor: default; }

        .agent-motion-active .agent-confirmation-cover,
        .agent-motion-active .agent-svg g[filter="url(#filter0_ddddii_964_1383257)"],
        .agent-motion-active .agent-svg rect[fill="url(#paint0_linear_964_1383257)"],
        .agent-motion-active .agent-svg rect[fill="url(#paint1_linear_964_1383257)"],
        .agent-motion-active .agent-svg g[filter="url(#filter3_dd_964_1383257)"],
        .agent-motion-active .agent-svg g[clip-path="url(#clip7_964_1383257)"] path,
        .agent-motion-active .agent-svg circle[cx="254.701"],
        .agent-motion-active .agent-svg circle[cx="254.701"] + path,
        .agent-motion-active .agent-svg .agent-connector-mask,
        .agent-motion-active .agent-svg g[filter="url(#filter7_ddddii_964_1383257)"],
        .agent-motion-active .agent-svg g[clip-path="url(#clip15_964_1383257)"],
        .agent-motion-active .agent-svg g[clip-path="url(#clip17_964_1383257)"],
        .agent-motion-active .agent-svg g[clip-path="url(#clip18_964_1383257)"],
        .agent-motion-active .agent-svg g[clip-path="url(#clip19_964_1383257)"],
        .agent-motion-active .agent-svg g[clip-path="url(#clip20_964_1383257)"],
        .agent-motion-active .agent-svg path[d^="M342.339 517.053"],
        .agent-motion-active .agent-svg path[d^="M519.648 521.145"],
        .agent-motion-active .agent-svg path[d^="M513 532.709"],
        .agent-motion-active .agent-svg path[d^="M511.886 517.59"] {
          animation-duration: ${INTRO_DURATION_MS}ms;
          /*
           * Default for opacity and colour beats. It used to be linear, on 19
           * of the 21 animations, which is a large part of why the sequence read
           * as sluggish — nothing arrived early. Positional beats override this
           * with an ease-out below.
           */
          animation-timing-function: cubic-bezier(.4, 0, .2, 1);
          /*
           * Runs ONCE and fills forwards, so the sequence settles on the result
           * instead of looping into a teardown half.
           */
          animation-iteration-count: 1;
          animation-direction: normal;
          animation-fill-mode: both;
        }

        .agent-motion-active .agent-svg g[filter="url(#filter0_ddddii_964_1383257)"] {
          animation-name: agent-workspace-flight;
          animation-timing-function: cubic-bezier(.33, 1, .68, 1);
        }
        .agent-motion-active .agent-svg rect[fill="url(#paint0_linear_964_1383257)"],
        .agent-motion-active .agent-svg rect[fill="url(#paint1_linear_964_1383257)"] { animation-name: agent-fade-mask; }
        .agent-motion-active .agent-confirmation-cover { animation-name: agent-confirmations-reveal; }
        .agent-motion-active .agent-svg g[filter="url(#filter3_dd_964_1383257)"] { animation-name: agent-file-focus; }
        .agent-motion-active .agent-svg g[clip-path="url(#clip7_964_1383257)"] path:first-child { animation-name: agent-file-icon-fill; }
        .agent-motion-active .agent-svg g[clip-path="url(#clip7_964_1383257)"] path:not(:first-child) { animation-name: agent-file-icon-stroke; }
        .agent-motion-active .agent-svg circle[cx="254.701"],
        .agent-motion-active .agent-svg circle[cx="254.701"] + path { animation-name: agent-reading-appear; }
        .agent-motion-active .agent-svg .agent-connector-mask {
          animation-name: agent-connector-draw;
          animation-timing-function: cubic-bezier(.33, 1, .68, 1);
        }
        .agent-motion-active .agent-svg g[filter="url(#filter7_ddddii_964_1383257)"] {
          animation-name: agent-panel-resolve;
          animation-timing-function: cubic-bezier(.33, 1, .68, 1);
        }
        .agent-motion-active .agent-svg g[clip-path="url(#clip15_964_1383257)"] { animation-name: agent-status-confirm; }
        .agent-motion-active .agent-svg g[clip-path="url(#clip17_964_1383257)"] { animation-name: agent-permission-one; }
        .agent-motion-active .agent-svg g[clip-path="url(#clip18_964_1383257)"] { animation-name: agent-permission-two; }
        .agent-motion-active .agent-svg g[clip-path="url(#clip19_964_1383257)"] { animation-name: agent-permission-three; }
        .agent-motion-active .agent-svg g[clip-path="url(#clip20_964_1383257)"] { animation-name: agent-permission-four; }
        .agent-motion-active .agent-svg path[d^="M342.339 517.053"] { animation-name: agent-audit-confirm; }
        .agent-motion-active .agent-svg path[d^="M519.648 521.145"],
        .agent-motion-active .agent-svg path[d^="M513 532.709"],
        .agent-motion-active .agent-svg path[d^="M511.886 517.59"] { animation-name: agent-sandbox-confirm; }

        /*
         * Every offset below is derived from BEATS, in ms. No hand-written
         * percentages. Each beat holds its start value, transitions once, and
         * holds the result to 100% — there is no reverse half.
         */
        @keyframes agent-workspace-flight {
          ${beat(BEATS.workspace, "transform: translate(174.5px, 222.9px); opacity: 1;", "transform: translate(0, 0); opacity: 1;")}
        }
        @keyframes agent-fade-mask {
          ${beat(BEATS.fadeMask, "opacity: 0;", "opacity: 1;")}
        }
        @keyframes agent-file-focus {
          ${beat(BEATS.authFocus, "opacity: 0;", "opacity: 1;")}
        }
        @keyframes agent-file-icon-fill {
          ${beat(BEATS.authFocus, "fill: #8f8f8f;", "fill: #0d76f2;")}
        }
        @keyframes agent-file-icon-stroke {
          ${beat(BEATS.authFocus, "stroke: #8f8f8f;", "stroke: #0d76f2;")}
        }
        @keyframes agent-reading-appear {
          ${beat(BEATS.reading, "opacity: 0;", "opacity: 1;")}
        }
        @keyframes agent-connector-draw {
          ${beat(BEATS.connector, "stroke-dashoffset: 1;", "stroke-dashoffset: 0;")}
        }
        /*
         * The only beat that is not a plain two-step: visibility flips one
         * millisecond before the move begins, exactly as the approved version
         * did, so the panel is not composited while it is still fully
         * transparent.
         */
        @keyframes agent-panel-resolve {
          0%, ${at(BEATS.panel[0])} { opacity: 0; transform: translateY(12px); visibility: hidden; }
          ${at(BEATS.panel[0] + 1)} { opacity: 0; transform: translateY(12px); visibility: visible; }
          ${at(BEATS.panel[1])}, 100% { opacity: 1; transform: translateY(0); visibility: visible; }
        }
        @keyframes agent-status-confirm {
          ${beat(BEATS.connected, "opacity: 0;", "opacity: 1;")}
        }
        @keyframes agent-permission-one {
          ${beat(BEATS.verbList, "opacity: 0;", "opacity: 1;")}
        }
        @keyframes agent-permission-two {
          ${beat(BEATS.verbRead, "opacity: 0;", "opacity: 1;")}
        }
        @keyframes agent-permission-three {
          ${beat(BEATS.verbWrite, "opacity: 0;", "opacity: 1;")}
        }
        @keyframes agent-permission-four {
          ${beat(BEATS.verbGlob, "opacity: 0;", "opacity: 1;")}
        }
        /*
         * The two consequences resolve out of a soft state: opacity AND blur.
         * Because hover replays this same timeline in reverse, the disappearance
         * re-blurs on its own — there is no separate reverse blur logic.
         */
        @keyframes agent-audit-confirm {
          ${beat(BEATS.audit, `opacity: 0; filter: blur(${CONSEQUENCE_BLUR_PX}px);`, "opacity: 1; filter: blur(0px);")}
        }
        @keyframes agent-sandbox-confirm {
          ${beat(BEATS.sandbox, `opacity: 0; filter: blur(${CONSEQUENCE_BLUR_PX}px);`, "opacity: 1; filter: blur(0px);")}
        }
        /*
         * Cover over the audit / sandbox row's static artwork. It lifts on the
         * sandbox beat, which is the relationship the approved version had.
         */
        @keyframes agent-confirmations-reveal {
          ${beat(BEATS.sandbox, "opacity: 1;", "opacity: 0;")}
        }

        @media (prefers-reduced-motion: reduce) {
          .agent-svg *, .agent-confirmation-cover { animation: none !important; }
          .agent-confirmation-cover { display: none; }
        }
      `}</style>
    </div>
  );
}
